def _extract_error_payload(payload: Dict[str, Any]) -> Dict[str, Any]:
    """
    Extract top-level error payload if nested; keep entire payload otherwise.
    Used only for improved assertion messages, not for schema validation.
    """
    if isinstance(payload, dict) and "error" in payload and isinstance(payload["error"], dict):
        return payload["error"]
    return payload


def _make_request_with_retries(
    api_client,
    endpoint: str,
    params: Dict[str, Any],
    retries: int,
    backoff_seconds: float,
) -> requests.Response:
    """
    Perform GET with simple retry on network errors. Status-code based retries are intentionally omitted
    to keep behavior predictable while honoring provided configuration.
    """
    attempt = 0
    while True:
        attempt += 1
        try:
            return api_client.get(endpoint=endpoint, params=params)
        except requests.RequestException:
            if attempt >= retries:
                raise
            time.sleep(backoff_seconds * attempt)


