@pytest.mark.parametrize(
    "case",
    argvalues=lambda astronomy_test_data: astronomy_test_data,  # filled by pytest at runtime
    ids=lambda case: f"{case.get('scenario', 'scenario')}|q={case.get('q')}|dt={case.get('dt')}|expect={case.get('statusCode')}",
    indirect=["case"],
)
def test_astronomy_get_table_driven(
    require_valid_api_key,  # ensures we skip if no API key
    api_client,
    swagger_validator: SwaggerSchemaValidator,
    endpoint_path: str,
    request_query_schema: Dict[str, Any],
    response_200_schema: Dict[str, Any],
    response_error_schema: Dict[str, Any],
    astronomy_test_data: List[Dict[str, Any]],
    valid_api_key: str,
    http_retry_settings: Dict[str, Any],
    case: Dict[str, Any],
):
    """
    Validate request schema, send GET /v1/astronomy.json, and validate response schema.
    Iterates over all objects from astronomy.json.json (table-driven).
    """
    # Build query params from test data (no hardcoded payloads)
    params: Dict[str, Any] = {
        "q": case["q"],
        "dt": case["dt"],
    }
    # Supply API key dynamically via fixture/config
    if valid_api_key:
        # Per WeatherAPI, API key is passed as a query parameter named 'key'
        params["key"] = valid_api_key

    # Validate the request before sending
    swagger_validator.validate_with_schema(params, request_query_schema)

    # Configure retries from config (if provided)
    retries = int(http_retry_settings.get("retries", 1))
    backoff_seconds = float(http_retry_settings.get("backoff_seconds", 0.5))

    # Send request
    response = _make_request_with_retries(
        api_client=api_client,
        endpoint=endpoint_path,
        params=params,
        retries=retries,
        backoff_seconds=backoff_seconds,
    )

    # Assert status code matches expected from test data
    expected_status = int(case["statusCode"])
    assert response.status_code == expected_status, f"Unexpected status code. Expected {expected_status}, got {response.status_code}. URL: {endpoint_path} Params: {params}"

    # Parse JSON body (response must be JSON per spec)
    try:
        body = response.json()
    except ValueError as e:
        pytest.fail(f"Response body is not valid JSON. Error: {e}. Raw: {response.text[:500]}")

    # Validate response using schema based on status code
    if response.status_code == 200:
        swagger_validator.validate_with_schema(body, response_200_schema)
    elif response.status_code in (400, 401, 403):
        swagger_validator.validate_with_schema(body, response_error_schema)
    else:
        # For any other unexpected code, still attempt a minimal validation.
        # Using a permissive schema avoids introducing custom logic, while ensuring it's valid JSON.
        swagger_validator.validate_with_schema(body, {"type": ["object", "array", "string", "number", "boolean", "null"]})


